package dev.zomboidmelee.boxing;
import java.util.*;import com.mojang.blaze3d.vertex.VertexConsumer;
/** Calibrates from the real attachment transform, clips in world coordinates, then returns to the same draw space. */
public final class Laser32{
 record Context(Object entity,double[] root){}static final ThreadLocal<Deque<Context>> CONTEXT=ThreadLocal.withInitial(ArrayDeque::new);static double[] view=Matrix32.identity();static Object world;static boolean warned;
 static double[] pose(Object stack){return Matrix32.read(R.call(R.call(stack,"last"),"pose"));}
 static double[] system(){return Matrix32.read(R.call(R.type("com.mojang.blaze3d.systems.RenderSystem"),"getModelViewMatrix"));}
 public static void stage(Object event){String stage=R.call(event,"getStage").toString();if(stage.toLowerCase(java.util.Locale.ROOT).endsWith("after_sky")){view=Matrix32.read(R.call(event,"getModelViewMatrix"));world=R.get(BoxingClient16.mc(),"level");}}
 public static void begin(Object entity,Object stack){double[] root=pose(stack);CONTEXT.get().push(new Context(entity,root));view=Matrix32.mul(system(),root);world=R.get(BoxingClient16.mc(),"level");}
 public static void end(){var s=CONTEXT.get();if(!s.isEmpty())s.pop();if(s.isEmpty())CONTEXT.remove();}
 static double ratio(){try{Class<?>c=R.type("com.tacz.guns.client.event.CameraSetupEvent");double a=R.num(R.call(R.get(c,"ITEM_MODEL_FOV_DYNAMICS"),"get")),b=R.num(R.call(R.get(c,"WORLD_FOV_DYNAMICS"),"get"));if(a>1&&a<179&&b>1&&b<179)return Math.tan(Math.toRadians(a/2))/Math.tan(Math.toRadians(b/2));}catch(IllegalStateException unavailable){}return 1;}
 static double[] mapping(double[] attachment,double[] root,boolean first,double[] mv,double fov){if(!first)return Matrix32.mul(Matrix32.inverse(root),attachment);double[] correction=Matrix32.identity();correction[10]=fov;return Matrix32.mul(Matrix32.inverse(view),Matrix32.mul(correction,Matrix32.mul(mv,attachment)));}
 static Object vec(double[]p){return R.make("net.minecraft.world.phys.Vec3",p[0],p[1],p[2]);}
 static double[] target(Object mc,Object entity){Object local=R.get(mc,"player");if(entity==local){Object hit=BoxingClient16.target(mc);if(hit!=null)try{double[]h=Matrix32.xyz(R.call(hit,"getLocation"));if(!"MISS".equals(R.call(hit,"getType").toString()))return h;double[]e=Matrix32.xyz(R.call(entity,"getEyePosition"));double dx=h[0]-e[0],dy=h[1]-e[1],dz=h[2]-e[2],n=Math.sqrt(dx*dx+dy*dy+dz*dz);if(n>.001)return new double[]{e[0]+dx/n*256,e[1]+dy/n*256,e[2]+dz/n*256};}catch(IllegalStateException unavailable){}}double[]eye=Matrix32.xyz(R.call(entity,"getEyePosition")),dir=Matrix32.xyz(R.call(entity,"getLookAngle"));return new double[]{eye[0]+dir[0]*256,eye[1]+dir[1]*256,eye[2]+dir[2]*256};}
 static double[] clip(Object entity,Object level,double[]start,double[]end){double dx=end[0]-start[0],dy=end[1]-start[1],dz=end[2]-start[2],distance=Math.sqrt(dx*dx+dy*dy+dz*dz);if(distance>256){double f=256/distance;end=new double[]{start[0]+dx*f,start[1]+dy*f,start[2]+dz*f};}Object ctx=R.make("net.minecraft.world.level.ClipContext",vec(start),vec(end),R.get(R.type("net.minecraft.world.level.ClipContext$Block"),"COLLIDER"),R.get(R.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),entity);Object hit=R.call(level,"clip",ctx);if("BLOCK".equals(R.call(hit,"getType").toString()))end=Matrix32.xyz(R.call(hit,"getLocation"));dx=end[0]-start[0];dy=end[1]-start[1];dz=end[2]-start[2];distance=Math.sqrt(dx*dx+dy*dy+dz*dz);if(distance>.004){double f=(distance-.003)/distance;end=new double[]{start[0]+dx*f,start[1]+dy*f,start[2]+dz*f};}return end;}
 static boolean nvg(Object p){try{return R.yes(R.call(p,"hasEffect",R.get(R.type("net.minecraft.world.effect.MobEffects"),"NIGHT_VISION")));}catch(IllegalStateException absent){return false;}}
 public static boolean render(Object stack,Object poses,Object context,Object path){boolean pushed=false;try{boolean first=R.yes(R.call(context,"firstPerson"));if(!first&&!context.toString().equals("THIRD_PERSON_RIGHT_HAND"))return true;Object mc=BoxingClient16.mc(),level=R.get(mc,"level");if(level==null||R.get(mc,"screen")!=null)return true;Context capture=CONTEXT.get().peek();Object entity=first?R.get(mc,"player"):capture==null?null:capture.entity();if(entity==null||!R.type("net.minecraft.world.entity.LivingEntity").isInstance(entity))return true;if(world!=level){view=Matrix32.identity();world=level;}Object camera=R.call(R.get(mc,"gameRenderer"),"getMainCamera");double[]cam=Matrix32.xyz(R.call(camera,"getPosition"));R.call(poses,"pushPose");pushed=true;for(Object part:(List<?>)path)R.call(part,"translateAndRotateAndScale",poses);double[]matrix=pose(poses),a=mapping(matrix,first?null:capture.root(),first,first?system():null,first?ratio():1),origin=Matrix32.point(a,0,0,0);for(int i=0;i<3;i++)origin[i]+=cam[i];double[]end=clip(entity,level,origin,target(mc,entity));for(int i=0;i<3;i++)end[i]-=cam[i];double[]local=Matrix32.point(Matrix32.inverse(a),end[0],end[1],end[2]);Class<?> beam=R.type("com.tacz.guns.client.model.functional.BeamRenderer");Object cfg=R.call(beam,"getLaserConfig",stack);int color=((Number)R.call(R.type("com.tacz.guns.util.LaserColorUtil"),"getLaserColor",stack,cfg)).intValue();double width=Math.max(.002,Math.min(.012,R.num(R.call(cfg,first?"getWidth":"getWidthThird"))));Object source=R.call(R.call(mc,"renderBuffers"),"bufferSource");Object type=R.call(R.type("com.tacz.guns.client.model.functional.BeamRenderer$LaserBeamRenderState"),"getLaserBeam");VertexConsumer v=(VertexConsumer)R.call(source,"getBuffer",type);draw(v,matrix,local,width,color,nvg(R.get(mc,"player")));return true;}catch(RuntimeException failure){if(!warned){warned=true;System.err.println("[GlobalMelee32] Laser calibration failed: "+failure);}return false;}finally{if(pushed)R.call(poses,"popPose");}}
 public static Object texture(Object original){return R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","zomboid_global_melee","textures/entity/laser32.png");}
 static int intensity(int c,double f){return (int)((c>>16&255)*f)<<16|(int)((c>>8&255)*f)<<8|(int)((c&255)*f);}
 static void vertex(VertexConsumer v,double[]m,double[]p,int color,int alpha,float u,float uv){double[]t=Matrix32.point(m,p[0],p[1],p[2]);v.addVertex((float)t[0],(float)t[1],(float)t[2]).setColor(color>>16&255,color>>8&255,color&255,alpha).setUv(u,uv).setUv2(240,240);}
 static void quad(VertexConsumer v,double[]m,double[]a,double[]b,double[]c,double[]d,int color,int alpha){vertex(v,m,a,color,alpha,0,0);vertex(v,m,b,color,alpha,0,1);vertex(v,m,c,color,alpha,1,1);vertex(v,m,d,color,alpha,1,0);}
 static double[] add(double[]a,double[]b,double scale){return new double[]{a[0]+b[0]*scale,a[1]+b[1]*scale,a[2]+b[2]*scale};}
 static void draw(VertexConsumer v,double[]m,double[]end,double width,int color,boolean night){double len=Math.sqrt(end[0]*end[0]+end[1]*end[1]+end[2]*end[2]);if(len<.001)return;double[]dir={end[0]/len,end[1]/len,end[2]/len},u=Math.abs(dir[1])<.9?new double[]{-dir[2],0,dir[0]}:new double[]{0,dir[2],-dir[1]};double n=Math.sqrt(u[0]*u[0]+u[1]*u[1]+u[2]*u[2]);for(int i=0;i<3;i++)u[i]/=n;double[]w={dir[1]*u[2]-dir[2]*u[1],dir[2]*u[0]-dir[0]*u[2],dir[0]*u[1]-dir[1]*u[0]},zero={0,0,0};for(double[]axis:new double[][]{u,w}){quad(v,m,add(zero,axis,-width),add(zero,axis,width),add(end,axis,width),add(end,axis,-width),intensity(color,night?.65:.30),251);quad(v,m,add(zero,axis,-width*.30),add(zero,axis,width*.30),add(end,axis,width*.30),add(end,axis,-width*.30),color,251);}double size=width*(night?3:2);quad(v,m,add(add(end,u,-size),w,-size),add(add(end,u,-size),w,size),add(add(end,u,size),w,size),add(add(end,u,size),w,-size),color,251);}
}
